  static const int crcExtra = 83;
  static const int minLength = 51;
  static const int maxLength = 54;

  /// Severity of status. Relies on the definitions within RFC-5424.
  final int severity;
  /// Status text message, without null termination character. UTF-8 encoded.
  final String text;
  /// Unique (opaque) identifier for this statustext message. May be used to reassemble a logical long-statustext message from a sequence of chunks. A value of zero indicates this is the only chunk in the sequence and the message can be emitted immediately. (extension)
  final int instanceId;
