  @override
  void encodeInto(ByteData d) {
    d.setUint8(0, severity);
    MavMessage.writeString(d, 1, 50, text);
    d.setUint16(51, instanceId, Endian.little);
    d.setUint8(53, chunkSeq);
  }

  @override
  Map<String, Object> toMap() => {
        'severity': severity,
        'text': text,
        'id': instanceId,
        'chunk_seq': chunkSeq,
      };
}

/// Obstacle distances in front of the sensor, starting from the left in increment degrees to the right
final class ObstacleDistance extends MavMessage {
  const ObstacleDistance({
    this.timeUsec = 0,
    this.sensorType = 0,
    this.distances = const [],
    this.increment = 0,
    this.minDistance = 0,
    this.maxDistance = 0,
    this.incrementF = 0.0,
    this.angleOffset = 0.0,
    this.frame = 0,
  });

  static const int msgId = 330;
  static const int crcExtra = 23;
  static const int minLength = 158;
  static const int maxLength = 167;

  /// Timestamp (UNIX Epoch time or time since system boot). The receiving end can infer timestamp format (since 1.1.1970 or since system boot) by checking for the magnitude of the number.
  final int timeUsec;
  /// Class id of the distance sensor type.
  final int sensorType;
  /// Distance of obstacles around the vehicle with index 0 corresponding to north + angle_offset, unless otherwise specified in the frame. A value of 0 is valid and means that the obstacle is practically touching the sensor. A value of max_distance +1 means no obstacle is present. A value of UINT16_MAX for unknown/not used. In a array element, one unit corresponds to 1cm.
  final List<int> distances;
  /// Angular width in degrees of each array element. Increment direction is clockwise. This field is ignored if increment_f is non-zero.
  final int increment;
  /// Minimum distance the sensor can measure.
  final int minDistance;
  /// Maximum distance the sensor can measure.
  final int maxDistance;
  /// Angular width in degrees of each array element as a float. If non-zero then this value is used instead of the uint8_t increment field. Positive is clockwise direction, negative is counter-clockwise. (extension)
  final double incrementF;
  /// Relative angle offset of the 0-index element in the distances array. Value of 0 corresponds to forward. Positive is clockwise direction, negative is counter-clockwise. (extension)
  final double angleOffset;
  /// Coordinate frame of reference for the yaw rotation and offset of the sensor data. Defaults to MAV_FRAME_GLOBAL, which is north aligned. For body-mounted sensors use MAV_FRAME_BODY_FRD, which is vehicle front aligned. (extension)
  final int frame;

  @override
  int get id => msgId;

  @override
  String get name => 'OBSTACLE_DISTANCE';

  @override
  int get payloadLength => maxLength;

  /// Decodes a payload already zero‑padded to [maxLength].
  factory ObstacleDistance.decode(ByteData d) => ObstacleDistance(
        timeUsec: d.getUint64(0, Endian.little),
        sensorType: d.getUint8(156),
        distances: [for (var i = 0; i < 72; i++) d.getUint16(8 + i * 2, Endian.little)],
        increment: d.getUint8(157),
        minDistance: d.getUint16(152, Endian.little),
        maxDistance: d.getUint16(154, Endian.little),
        incrementF: d.getFloat32(158, Endian.little),
        angleOffset: d.getFloat32(162, Endian.little),
        frame: d.getUint8(166),
      );

  @override
  void encodeInto(ByteData d) {
    d.setUint64(0, timeUsec, Endian.little);
    for (var i = 0; i < 72 && i < distances.length; i++) {
      d.setUint16(8 + i * 2, distances[i], Endian.little);
    }
    d.setUint16(152, minDistance, Endian.little);
    d.setUint16(154, maxDistance, Endian.little);
    d.setUint8(156, sensorType);
    d.setUint8(157, increment);
    d.setFloat32(158, incrementF, Endian.little);
    d.setFloat32(162, angleOffset, Endian.little);
    d.setUint8(166, frame);
  }

  @override
  Map<String, Object> toMap() => {
        'time_usec': timeUsec,
        'sensor_type': sensorType,
        'distances': distances,
        'increment': increment,
        'min_distance': minDistance,
        'max_distance': maxDistance,
        'increment_f': incrementF,
        'angle_offset': angleOffset,
        'frame': frame,
      };
}

